test "t03 mediana" {
    const a = [_]i64{ 3, 1, 2 };
    try std.testing.expectEqual(@as(f64, 2.0), try median(std.testing.allocator, &a));
    const b = [_]i64{ 4, 1, 3, 2 };
    try std.testing.expectEqual(@as(f64, 2.5), try median(std.testing.allocator, &b));
    const c = [_]i64{7};
    try std.testing.expectEqual(@as(f64, 7.0), try median(std.testing.allocator, &c));
    const empty = [_]i64{};
    try std.testing.expectError(error.EmptyInput, median(std.testing.allocator, &empty));
}
